/**
 * Pages published as static files with the data, not built into the SPA.
 *
 * /hgab/2027/we-are-not-ignorant is generated by `npm run build:hgab-not-ignorant`
 * into data/hgab/2027/we-are-not-ignorant.html and published by
 * `npm run upload:hgab` to the data host, so updating it means regenerating
 * and uploading, never redeploying. Local development serves the data tree
 * through the assets binding (public/data); production excludes data/** from
 * the assets (scripts/prepare-deploy-assets.ts) and reads the data host.
 */

const DATA_HOST = "https://budget-assets.bettergov.ph";

/** Path → data key, and the marker the generated file carries. */
export const STATIC_PAGES: Record<string, { key: string; marker: string }> = {
  "/hgab/2027/we-are-not-ignorant": { key: "hgab/2027/we-are-not-ignorant.html", marker: "hgab-we-are-not-ignorant" },
};

export function staticPageFor(pathname: string): { key: string; marker: string } | null {
  return STATIC_PAGES[pathname.replace(/\/+$/, "") || "/"] ?? null;
}

const HTML_HEADERS = {
  "content-type": "text/html; charset=utf-8",
  "cache-control": "public, max-age=300",
  "x-content-type-options": "nosniff",
};

export async function serveStaticPage(request: Request, env: Env, url: URL, page: { key: string; marker: string }): Promise<Response> {
  if (request.method !== "GET" && request.method !== "HEAD") {
    return new Response("Method not allowed", { status: 405, headers: { allow: "GET, HEAD" } });
  }
  const body = (text: string | ReadableStream | null) => (request.method === "HEAD" ? null : text);

  // Development: the local data tree, when the assets binding has it (the SPA
  // fallback answers 200 for missing files, so check the marker).
  const local = await env.ASSETS.fetch(new Request(new URL(`/data/${page.key}`, url)));
  if (local.ok) {
    const text = await local.text();
    if (text.includes(page.marker)) return new Response(body(text), { status: 200, headers: HTML_HEADERS });
  }

  const res = await fetch(`${DATA_HOST}/${page.key}`, { cf: { cacheTtl: 300, cacheEverything: true } } as RequestInit);
  if (!res.ok || !res.body) {
    return new Response("This page is being regenerated. Please try again in a minute.", {
      status: 503,
      headers: { "content-type": "text/plain; charset=utf-8", "retry-after": "60" },
    });
  }
  return new Response(body(res.body), { status: 200, headers: HTML_HEADERS });
}
